import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, BookOpen, Check, CheckCircle2, ChevronRight, Database, FileSpreadsheet, FlaskConical, Gauge, Layers3, LayoutDashboard, Loader2, LogOut, Menu, Plus, Search, Settings2, ShieldCheck, Sparkles, Upload, X, TriangleAlert } from 'lucide-react';
import { api, calibrationNames, date, decimal, errorMessage, modelNames, number, percent, type Auth, type Dashboard, type Dataset, type Prediction, type Run, type RunConfig } from './api';
import { MissingChart, ProbabilityHistogram, ReliabilityChart } from './Charts';

type Page = 'overview' | 'datasets' | 'runs' | 'scoring' | 'research';
const navigation = [
  { key: 'overview', name: '工作台', subtitle: 'Overview', icon: LayoutDashboard },
  { key: 'datasets', name: '数据资产', subtitle: 'Datasets', icon: Database },
  { key: 'runs', name: '分析实验', subtitle: 'Experiments', icon: FlaskConical },
  { key: 'scoring', name: '批量评分', subtitle: 'Batch scoring', icon: BarChart3 },
  { key: 'research', name: '方法说明', subtitle: 'Methods', icon: BookOpen },
];

function Brand() { return <div className="brand"><div className="brand-mark"><span/><i/></div><div><strong>AWARE</strong><small>信用数据分析工作台</small></div></div>; }
function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost'; children: ReactNode }) { return <button className={`button ${variant} ${className}`} {...props}>{children}</button>; }
function Badge({ children, tone = '' }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Status({ run }: { run: Run }) { const labels = { queued: '等待训练', running: '训练中', completed: '已完成', failed: '未完成' }; return <Badge tone={run.status}><span className="status-dot"/>{labels[run.status]}</Badge>; }
function Alert({ children, warning = false }: { children: ReactNode; warning?: boolean }) { return <div className={`alert ${warning ? 'warning' : 'error'}`} role={warning ? 'status' : 'alert'}><TriangleAlert size={17}/><div>{children}</div></div>; }
function Empty({ icon: Icon = Database, title, detail, action }: { icon?: typeof Database; title: string; detail: string; action?: ReactNode }) { return <div className="empty"><div className="empty-icon"><Icon size={28}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>; }
function Loading({ text = '正在加载工作台…' }: { text?: string }) { return <div className="loading"><Loader2 className="spin" size={26}/><span>{text}</span></div>; }
function SectionTitle({ title, description, action }: { title: string; description?: string; action?: ReactNode }) { return <div className="section-title"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>; }
function Download({ path, children, className = '' }: { path: string; children: ReactNode; className?: string }) { return <a href={`/api${path}`} className={`button secondary ${className}`} download><ArrowDownToLine size={16}/>{children}</a>; }
function Source({ dataset }: { dataset?: Dataset }) { return dataset?.source === 'demo' ? <Badge tone="synthetic"><Sparkles size={11}/>合成示例</Badge> : <Badge>用户上传</Badge>; }

export default function App() {
  const [auth, setAuth] = useState<Auth | null>(null);
  const [authError, setAuthError] = useState('');
  const [route, setRoute] = useState(window.location.hash.slice(1) || 'overview');
  const [mobile, setMobile] = useState(false);
  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
  const [datasets, setDatasets] = useState<Dataset[]>([]);
  const [runs, setRuns] = useState<Run[]>([]);
  const [predictions, setPredictions] = useState<Prediction[]>([]);
  const [loadError, setLoadError] = useState('');
  const [newRun, setNewRun] = useState<string | null>(null);
  const [toast, setToast] = useState('');
  const initialLoad = useRef(false);
  const page = (route.split('/')[0] || 'overview') as Page;
  const activeNav = navigation.find(item => item.key === page) || navigation[0];
  const go = useCallback((next: string) => { window.location.hash = next; setRoute(next); setMobile(false); window.scrollTo({ top: 0, behavior: 'smooth' }); }, []);
  const checkAuth = useCallback(async () => { try { setAuthError(''); setAuth(await api<Auth>('/auth/status')); } catch (error) { setAuthError(errorMessage(error)); } }, []);
  const refresh = useCallback(async () => {
    try {
      const [summary, data, experiments, batches] = await Promise.all([api<Dashboard>('/dashboard'), api<{ items: Dataset[] }>('/datasets'), api<{ items: Run[] }>('/runs'), api<{ items: Prediction[] }>('/predictions')]);
      setDashboard(summary); setDatasets(data.items); setRuns(experiments.items); setPredictions(batches.items); setLoadError(''); initialLoad.current = true;
    } catch (error) { setLoadError(errorMessage(error)); }
  }, []);
  useEffect(() => { void checkAuth(); }, [checkAuth]);
  useEffect(() => { const listener = () => setRoute(window.location.hash.slice(1) || 'overview'); window.addEventListener('hashchange', listener); return () => window.removeEventListener('hashchange', listener); }, []);
  useEffect(() => { if (auth?.authenticated) void refresh(); }, [auth?.authenticated, refresh]);
  useEffect(() => { if (!auth?.authenticated) return; const id = window.setInterval(() => { if (!document.hidden) void refresh(); }, runs.some(run => ['queued', 'running'].includes(run.status)) ? 2500 : 12000); return () => window.clearInterval(id); }, [auth?.authenticated, runs, refresh]);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(''), 4500); return () => window.clearTimeout(id); }, [toast]);
  const logout = async () => { try { await api('/auth/logout', { method: 'POST' }); setDashboard(null); setRuns([]); setDatasets([]); initialLoad.current = false; await checkAuth(); } catch (error) { setToast(errorMessage(error)); } };
  if (authError) return <div className="auth-shell"><div className="auth-card"><Brand/><Alert>{authError}</Alert><p className="muted">暂时无法连接分析服务，请确认后端服务已启动。</p><Button onClick={() => void checkAuth()}>重新连接</Button></div></div>;
  if (!auth) return <div className="auth-shell"><Loading/></div>;
  if (!auth.authenticated) return <AuthScreen auth={auth} onSuccess={checkAuth}/>;
  const selectedRun = route.startsWith('runs/') ? runs.find(run => run.id === route.split('/')[1]) : undefined;
  return <div className="app-shell">
    {mobile && <button className="sidebar-backdrop" aria-label="关闭导航" onClick={() => setMobile(false)}/>}
    <aside className={`sidebar ${mobile ? 'open' : ''}`}><Brand/><div className="workspace-label">工作空间 <span>WORKSPACE</span></div><nav aria-label="主导航">{navigation.map(item => <button key={item.key} className={`nav-item ${page === item.key ? 'active' : ''}`} aria-current={page === item.key ? 'page' : undefined} onClick={() => go(item.key)}><item.icon size={19}/><span>{item.name}</span>{item.key === 'runs' && runs.some(run => run.status === 'running') && <i className="nav-live"/>}</button>)}</nav><div className="sidebar-note"><Layers3 size={23}/><strong>看见数据背后的不确定性</strong><p>从缺失值处理到概率校准，<br/>保留分析的每一步依据。</p><button onClick={() => go('research')}>了解分析方法 <ArrowUpRight size={14}/></button></div><div className="sidebar-bottom"><span className="avatar">A</span><div><strong>{auth.demo_mode ? '产品演示空间' : '个人分析空间'}</strong><small><i/>{auth.demo_mode ? '本地运行 · 演示模式' : '本地运行 · 安全会话'}</small></div>{!auth.demo_mode && <button aria-label="退出登录" title="退出登录" onClick={() => void logout()}><LogOut size={17}/></button>}</div></aside>
    <main className="main"><header className="topbar"><div className="breadcrumbs"><button className="mobile-toggle" aria-label="展开导航" onClick={() => setMobile(true)}><Menu size={21}/></button><span>工作空间</span><ChevronRight size={14}/><strong>{activeNav.name}</strong>{selectedRun && <><ChevronRight size={14}/><span className="breadcrumb-run">实验详情</span></>}</div><div className="topbar-right"><span className="local-status"><i/>{loadError ? '服务连接待恢复' : '分析服务在线'}</span>{auth.demo_mode && <Badge tone="synthetic">DEMO 演示</Badge>}<span className="top-avatar">A</span></div></header>
      <div className="content">
        {loadError && <div className="load-alert"><Alert>{loadError}</Alert><Button variant="secondary" onClick={() => void refresh()}>重试</Button></div>}
        {!initialLoad.current && !loadError ? <Loading/> : <>
          {page === 'overview' && <Overview dashboard={dashboard} datasets={datasets} go={go} onNew={() => setNewRun('')}/>}
          {page === 'datasets' && <DatasetsPage datasets={datasets} onChange={refresh} onNew={setNewRun} notify={setToast}/>}
          {page === 'runs' && !route.includes('/') && <RunsPage runs={runs} datasets={datasets} go={go} onNew={() => setNewRun('')}/>}
          {page === 'runs' && route.includes('/') && (selectedRun ? <RunDetail key={selectedRun.id} run={selectedRun} dataset={datasets.find(dataset => dataset.id === selectedRun.dataset_id)} go={go}/> : <Empty icon={FlaskConical} title="未找到这次分析" detail="该实验可能不存在，请返回分析实验列表。" action={<Button onClick={() => go('runs')}>返回列表</Button>}/>) }
          {page === 'scoring' && <ScoringPage runs={runs} predictions={predictions} onChange={refresh} notify={setToast} initialRunId={route.split('/')[1] || ''}/>}
          {page === 'research' && <ResearchPage/>}
          {!navigation.some(item => item.key === page) && <Empty title="页面不存在" detail="返回工作台继续分析。" action={<Button onClick={() => go('overview')}>返回工作台</Button>}/>}
        </>}
        <footer className="page-footer"><span>AWARE <span className="footer-dot">·</span> MISSINGNESS-AWARE CREDIT ANALYTICS</span><span>概率用于分析参考，不构成自动信贷决策</span></footer>
      </div>
    </main>
    {newRun !== null && <NewRunModal datasets={datasets} initialDataset={newRun} onClose={() => setNewRun(null)} onCreated={async run => { setNewRun(null); await refresh(); go(`runs/${run.id}`); setToast('分析已提交，训练进度会自动更新。'); }}/>}
    {toast && <div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button aria-label="关闭通知" onClick={() => setToast('')}><X size={15}/></button></div>}
  </div>;
}

function AuthScreen({ auth, onSuccess }: { auth: Auth; onSuccess: () => Promise<void> }) {
  const [password, setPassword] = useState(''), [busy, setBusy] = useState(false), [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { await api(auth.configured ? '/auth/login' : '/auth/setup', { method: 'POST', body: JSON.stringify({ password }) }); await onSuccess(); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <div className="auth-shell"><div className="auth-decoration"><div className="eyebrow">MAKE UNCERTAINTY VISIBLE</div><h1>缺失可见，<br/>概率可解释。</h1><p>一个连接数据质量、模型分析与概率校准的工作空间。</p></div><div className="auth-card"><Brand/><h2>{auth.configured ? '欢迎回到工作台' : '创建你的分析空间'}</h2><p className="muted">{auth.configured ? '输入工作空间密码，继续你的信用数据分析。' : '设置至少 12 个字符的密码，保护本地数据与分析结果。'}</p><form onSubmit={submit}><label className="field">工作空间密码<input type="password" autoComplete={auth.configured ? 'current-password' : 'new-password'} required minLength={12} value={password} onChange={event => setPassword(event.target.value)} placeholder="至少 12 个字符" autoFocus/></label>{error && <Alert>{error}</Alert>}<Button type="submit" disabled={busy} className="full">{busy ? <Loader2 size={16} className="spin"/> : <ArrowRight size={16}/>} {auth.configured ? '进入工作台' : '创建并进入'}</Button></form><div className="auth-note"><ShieldCheck size={15}/>单用户本地工作空间 · 数据保存在当前服务</div></div></div>;
}

function Overview({ dashboard, datasets, go, onNew }: { dashboard: Dashboard | null; datasets: Dataset[]; go: (page: string) => void; onNew: () => void }) {
  const latest = datasets[0];
  const stats = [
    { label: '数据资产', value: dashboard?.datasets_count, icon: Database, unit: '份数据集', note: '已导入并完成质量检查', route: 'datasets' },
    { label: '分析实验', value: dashboard?.runs_count, icon: FlaskConical, unit: '次分析', note: '每次实验独立保存配置', route: 'runs' },
    { label: '完成训练', value: dashboard?.completed_runs, icon: CheckCircle2, unit: '份结果', note: '可查看校准表现与报告', route: 'runs' },
    { label: '批量评分', value: dashboard?.prediction_batches, icon: BarChart3, unit: '个批次', note: '使用已冻结的模型推断', route: 'scoring' },
  ];
  return <><div className="page-heading"><div><div className="eyebrow">YOUR ANALYTICS WORKSPACE</div><h1>工作台概览</h1><p>从数据质量出发，让信用分析更有依据。</p></div><Button onClick={onNew}><Plus size={17}/>新建分析</Button></div>
    <section className="hero"><div className="hero-copy"><div className="hero-kicker"><span/>AWARE · 可解释的分析流程</div><h2>缺失可见，<br/>概率<span>可解释。</span></h2><p>识别数据中的缺失模式，对比模型与校准方法，<br className="desktop-break"/>在同一工作空间连接研究发现与真实分析。</p><div className="hero-actions"><button className="hero-button" onClick={onNew}>开始一次分析 <ArrowRight size={17}/></button><button className="hero-link" onClick={() => go('research')}>了解研究方法 <ArrowUpRight size={15}/></button></div></div><div className="hero-diagram" aria-hidden="true"><div className="diagram-label">FROM DATA TO CONFIDENCE</div><div className="diagram-grid"><div className="diagram-node node-data"><Database size={20}/><span>数据质量</span><small>Missingness</small></div><div className="diagram-connector"/><div className="diagram-node node-model"><Layers3 size={20}/><span>模型分析</span><small>Modeling</small></div><div className="diagram-connector"/><div className="diagram-node node-calibration"><Gauge size={20}/><span>概率校准</span><small>Calibration</small></div></div><div className="diagram-track"><i/><span>独立划分</span><i/><span>冻结预处理</span><i/><span>留出集评估</span></div><div className="diagram-caption">分析有边界，结果可追溯。</div></div></section>
    <div className="stats-grid">{stats.map(stat => <button className="stat-card" key={stat.label} onClick={() => go(stat.route)}><div className="stat-top"><span>{stat.label}</span><stat.icon size={18}/></div><div className="stat-value">{number(stat.value)}<small>{stat.unit}</small></div><div className="stat-note">{stat.note}<ArrowUpRight size={14}/></div></button>)}</div>
    <div className="overview-grid"><section className="card recent-card"><SectionTitle title="最近的分析" description="保存每一次探索，随时回到结果。" action={<button className="text-button" onClick={() => go('runs')}>查看全部 <ArrowRight size={14}/></button>}/>{dashboard?.recent_runs.length ? <RunTable runs={dashboard.recent_runs.slice(0, 4)} datasets={datasets} go={go} compact/> : <Empty icon={FlaskConical} title="开始你的第一个分析" detail="选择数据集，定义正类事件，比较模型的概率表现。" action={<Button variant="secondary" onClick={onNew}>新建分析</Button>}/>}</section><section className="card quality-card"><SectionTitle title="数据质量快照" action={<Database size={19} className="muted"/>}/>{latest ? <><div className="quality-dataset"><div className="file-icon"><FileSpreadsheet size={21}/></div><div><strong className="truncate">{latest.name}</strong><small>{number(latest.rows)} 行 · {latest.column_count} 个字段</small></div></div><div className="quality-ring-row"><div className="quality-ring" style={{ background: `conic-gradient(#278670 ${360 * (1 - latest.missing_rate)}deg, #e8eeea 0)` }}><span><strong>{percent(1 - latest.missing_rate, 1)}</strong><small>数据完整率</small></span></div><div className="quality-facts"><div><span>缺失单元格占比</span><strong>{percent(latest.missing_rate)}</strong></div><div><span>含缺失字段</span><strong>{latest.columns.filter(column => column.missing_count > 0).length} / {latest.column_count}</strong></div></div></div><div className="quality-bottom"><Source dataset={latest}/><button className="text-button" onClick={() => go('datasets')}>查看数据 <ArrowRight size={14}/></button></div></> : <Empty title="还没有数据" detail="上传 CSV 或导入合成示例。"/>}</section></div>
    <section className="workflow"><SectionTitle title="从数据到结果，只需三步" description="每一步都有清晰的输入、输出与分析边界。"/><div className="workflow-steps">{[{ n: '01', icon: Upload, title: '准备数据', text: '导入 CSV，了解字段类型与缺失分布。', page: 'datasets' }, { n: '02', icon: Settings2, title: '创建分析', text: '明确正类事件，对比模型与概率校准。', page: 'runs' }, { n: '03', icon: BarChart3, title: '应用与复核', text: '使用冻结模型评分，导出结果供人工研判。', page: 'scoring' }].map(step => <button className="workflow-step" key={step.n} onClick={() => go(step.page)}><span className="step-number">{step.n}</span><div className="step-icon"><step.icon size={19}/></div><div><h3>{step.title}</h3><p>{step.text}</p></div><ArrowUpRight size={17}/></button>)}</div></section>
    <div className="research-strip"><div className="research-strip-icon"><BookOpen size={21}/></div><div><strong>了解这套分析方法</strong><p>先检查缺失，再比较模型的区分能力和概率可靠性；工作台中的指标来自当前数据的实际训练。</p></div><button className="text-button" onClick={() => go('research')}>查看方法说明 <ArrowUpRight size={15}/></button></div>
  </>;
}

function RunTable({ runs, datasets, go, compact = false }: { runs: Run[]; datasets: Dataset[]; go: (page: string) => void; compact?: boolean }) {
  return <div className="table-wrap"><table className="run-table"><thead><tr><th>分析名称 / 数据集</th><th>状态</th>{!compact && <th>模型</th>}<th>创建时间</th><th><span className="sr-only">操作</span></th></tr></thead><tbody>{runs.map(run => <tr key={run.id}><td><button className="table-name" onClick={() => go(`runs/${run.id}`)}><span className="run-icon"><FlaskConical size={17}/></span><span><strong>{run.name}</strong><small>{run.dataset_name}{datasets.find(dataset => dataset.id === run.dataset_id)?.source === 'demo' && <span className="inline-synthetic">合成示例</span>}</small></span></button></td><td><Status run={run}/>{['queued', 'running'].includes(run.status) && <div className="inline-progress"><span style={{ width: `${run.progress}%` }}/></div>}</td>{!compact && <td><span className="muted small">{run.config.models.map(model => modelNames[model] || model).join(' / ')}</span></td>}<td className="date-cell">{date(run.created_at)}</td><td><button className="icon-button" aria-label={`查看 ${run.name}`} onClick={() => go(`runs/${run.id}`)}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>;
}

function DatasetsPage({ datasets, onChange, onNew, notify }: { datasets: Dataset[]; onChange: () => Promise<void>; onNew: (datasetId: string) => void; notify: (text: string) => void }) {
  const [selectedId, setSelectedId] = useState(''), [query, setQuery] = useState(''), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const uploadRef = useRef<HTMLInputElement>(null);
  const selected = datasets.find(dataset => dataset.id === selectedId) || datasets[0];
  const filtered = datasets.filter(dataset => dataset.name.toLowerCase().includes(query.toLowerCase()));
  async function upload(file?: File) { if (!file) return; setBusy(true); setError(''); try { const form = new FormData(); form.append('file', file); const dataset = await api<Dataset>('/datasets', { method: 'POST', body: form }); await onChange(); setSelectedId(dataset.id); notify('数据已导入，字段与缺失情况已就绪。'); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); if (uploadRef.current) uploadRef.current.value = ''; } }
  async function importDemo() { setBusy(true); setError(''); try { const dataset = await api<Dataset>('/datasets/demo', { method: 'POST' }); await onChange(); setSelectedId(dataset.id); notify('合成示例已导入。'); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <><div className="page-heading"><div><div className="eyebrow">KNOW YOUR DATA</div><h1>数据资产</h1><p>先理解数据，再开始建模。所有分析从一份清晰的数据开始。</p></div><div className="actions"><Button variant="secondary" disabled={busy} onClick={() => void importDemo()}><Sparkles size={16}/>导入合成示例</Button><Button disabled={busy} onClick={() => uploadRef.current?.click()}>{busy ? <Loader2 className="spin" size={16}/> : <Upload size={16}/>}上传 CSV</Button></div></div><input ref={uploadRef} type="file" className="sr-only" accept=".csv,text/csv" aria-label="上传 CSV 数据集" onChange={event => void upload(event.target.files?.[0])}/>
    {error && <Alert>{error}</Alert>}
    <div className="data-upload-note"><FileSpreadsheet size={18}/><span>支持 UTF-8 / BOM 编码的 CSV，最大 20 MiB、50,000 行、100 列。空值与 “?” 记为缺失。</span></div>
    {!datasets.length ? <section className="card"><Empty title="把第一份数据带进来" detail="上传你自己的数据，或导入带有缺失值的合成信用数据体验完整流程。" action={<Button disabled={busy} onClick={() => void importDemo()}><Sparkles size={16}/>导入合成示例</Button>}/></section> : <div className="dataset-layout"><section className="card dataset-list"><div className="dataset-list-head"><h2>全部数据集 <span>{datasets.length}</span></h2><label className="search-field"><Search size={15}/><input aria-label="搜索数据集" value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索数据集…"/></label></div>{filtered.length ? filtered.map(dataset => <button className={`dataset-item ${selected?.id === dataset.id ? 'selected' : ''}`} key={dataset.id} onClick={() => setSelectedId(dataset.id)}><div className="file-icon"><FileSpreadsheet size={20}/></div><div><strong className="truncate">{dataset.name}</strong><small>{number(dataset.rows)} 行 · {dataset.column_count} 字段</small><Source dataset={dataset}/></div><ChevronRight size={15}/></button>) : <p className="padded muted">没有匹配的数据集。</p>}</section><div className="dataset-detail">{selected && <><section className="card"><SectionTitle title={selected.name} description={`导入于 ${date(selected.created_at)}`} action={<Source dataset={selected}/>}/><div className="dataset-stats"><div><span>样本行数</span><strong>{number(selected.rows)}</strong></div><div><span>字段数量</span><strong>{selected.column_count}</strong></div><div><span>整体缺失率</span><strong>{percent(selected.missing_rate)}</strong></div><div><span>数值 / 类别</span><strong>{selected.columns.filter(column => column.kind === 'numeric').length}<small> / {selected.columns.filter(column => column.kind === 'categorical').length}</small></strong></div></div>{selected.source === 'demo' && <div className="synthetic-note"><Sparkles size={15}/>本数据由程序合成，仅供演示流程；模型表现不代表真实信贷效果。</div>}{selected.warnings.map((warning, index) => <Alert key={index} warning>{warning}</Alert>)}<div className="card-actions"><Download path={`/datasets/${selected.id}/download`}>下载原始数据</Download><Button onClick={() => onNew(selected.id)}><Plus size={16}/>使用此数据分析</Button></div></section><section className="card"><SectionTitle title="字段与缺失分布" description="类型由数据初步识别，可在创建分析时调整类别字段。"/><div className="table-wrap"><table><thead><tr><th>字段名称</th><th>类型</th><th>不同取值</th><th>缺失率</th><th>取值示例</th></tr></thead><tbody>{selected.columns.map(column => <tr key={column.name}><td className="mono">{column.name}</td><td><Badge>{column.kind === 'numeric' ? '数值' : '类别'}</Badge></td><td>{number(column.unique_count)}</td><td><div className="cell-bar"><span><i style={{ width: `${column.missing_rate * 100}%` }}/></span>{percent(column.missing_rate)}</div></td><td className="sample-cell" title={column.sample_values.join(' · ')}>{column.sample_values.slice(0, 3).join(' · ') || '—'}</td></tr>)}</tbody></table></div></section><section className="card"><SectionTitle title="数据预览" description={`展示前 ${selected.preview.length} 行；“—” 表示缺失。`}/><div className="table-wrap preview-table"><table><thead><tr>{selected.columns.map(column => <th key={column.name}>{column.name}</th>)}</tr></thead><tbody>{selected.preview.map((row, index) => <tr key={index}>{selected.columns.map(column => <td key={column.name}>{row[column.name] ?? <span className="missing-value">—</span>}</td>)}</tr>)}</tbody></table></div></section></>}</div></div>}
  </>;
}

function RunsPage({ runs, datasets, go, onNew }: { runs: Run[]; datasets: Dataset[]; go: (page: string) => void; onNew: () => void }) {
  const [filter, setFilter] = useState('all'), [query, setQuery] = useState('');
  const filtered = runs.filter(run => (filter === 'all' || run.status === filter || (filter === 'active' && ['queued', 'running'].includes(run.status))) && `${run.name} ${run.dataset_name}`.toLowerCase().includes(query.toLowerCase()));
  return <><div className="page-heading"><div><div className="eyebrow">REPRODUCIBLE EXPERIMENTS</div><h1>分析实验</h1><p>比较模型判别能力与概率可信度，保留可复现的实验记录。</p></div><Button onClick={onNew}><Plus size={17}/>新建分析</Button></div><div className="info-strip"><ShieldCheck size={19}/><span>训练集学习模型，校准集拟合概率映射，测试集独立评估。所有候选结果完整展示。</span></div><section className="card"><div className="table-toolbar"><div className="tabs" role="group" aria-label="按状态筛选">{[{ key: 'all', label: '全部实验' }, { key: 'completed', label: '已完成' }, { key: 'active', label: '进行中' }, { key: 'failed', label: '未完成' }].map(item => <button key={item.key} className={filter === item.key ? 'active' : ''} onClick={() => setFilter(item.key)}>{item.label}</button>)}</div><label className="search-field"><Search size={15}/><input aria-label="搜索分析实验" value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索分析名称或数据集…"/></label></div>{filtered.length ? <RunTable runs={filtered} datasets={datasets} go={go}/> : <Empty icon={FlaskConical} title={runs.length ? '没有匹配的实验' : '你的第一份分析，从这里开始'} detail={runs.length ? '调整搜索关键词或状态筛选。' : '选择数据集、正类事件与模型，提交后即可查看训练进度。'} action={!runs.length && <Button onClick={onNew}>创建分析</Button>}/>}</section></>;
}

function RunDetail({ run, dataset, go }: { run: Run; dataset?: Dataset; go: (page: string) => void }) {
  const [model, setModel] = useState(run.config.models[0] || 'logistic'), [calibration, setCalibration] = useState('raw');
  const result = run.result;
  const metrics = result?.metrics.filter(metric => metric.model === model) || [];
  const metric = metrics.find(item => item.calibration === calibration);
  return <><button className="back-button" onClick={() => go('runs')}><ArrowLeft size={15}/>返回分析实验</button><div className="page-heading"><div><div className="eyebrow">EXPERIMENT REPORT</div><h1>{run.name}</h1><div className="heading-meta"><Status run={run}/><Source dataset={dataset}/><span>{run.dataset_name}</span><span>{date(run.created_at)}</span></div></div>{run.status === 'completed' && <div className="actions"><Download path={`/runs/${run.id}/report`}>导出分析报告</Download><Button onClick={() => go(`scoring/${run.id}`)}><BarChart3 size={16}/>用于批量评分</Button></div>}</div>
    {run.status === 'failed' && <Alert>{run.error || run.message || '此次训练未能完成。请检查数据和分析配置。'}</Alert>}
    {['queued', 'running'].includes(run.status) && <section className="card training-card"><div className="training-icon"><Loader2 className="spin" size={27}/></div><h2>{run.status === 'queued' ? '分析已排队，即将开始' : '正在训练与校准模型'}</h2><p>{run.message || '正在准备分析数据…'}</p><div className="training-progress"><span style={{ width: `${run.progress}%` }}/></div><span className="muted small">{run.progress}% · 进度自动更新，可离开此页面稍后回来</span></section>}
    {result && <><div className="event-banner"><div className="event-icon"><Gauge size={23}/></div><div><small>本次分析的正类事件</small><strong>{result.positive_label}</strong></div><div className="event-explanation">概率越高，表示该事件发生的模型估计可能性越高。<br/>标签定义：<code>{run.config.target_column} = {run.config.positive_value}</code></div></div>{result.warnings.map((warning, index) => <Alert key={index} warning>{warning}</Alert>)}
      <section className="card comparison-panel"><div className="section-title"><div><h2>模型表现</h2><p>在独立测试集上评估；切换模型与校准方法查看各项指标。</p></div><div className="metric-controls"><label><span className="sr-only">选择结果模型</span><select value={model} onChange={event => setModel(event.target.value)}>{[...new Set(result.metrics.map(item => item.model))].map(value => <option key={value} value={value}>{modelNames[value] || value}</option>)}</select></label><div className="segmented" role="group" aria-label="选择校准方法">{['raw', 'platt', 'isotonic'].map(value => <button className={calibration === value ? 'active' : ''} key={value} onClick={() => setCalibration(value)}>{value === 'raw' ? '原始' : value === 'platt' ? 'Platt' : 'Isotonic'}</button>)}</div></div></div><div className="metric-grid">{[{ label: 'ROC AUC', value: metric?.auc, direction: '越高越好', explanation: '区分正负样本的能力' }, { label: 'Brier Score', value: metric?.brier, direction: '越低越好', explanation: '概率预测的均方误差' }, { label: 'ECE', value: metric?.ece, direction: '越低越好', explanation: '预测概率与实际频率偏差' }, { label: 'F1 Score', value: metric?.f1, direction: '阈值 0.5', explanation: '精确率与召回率的调和平均' }].map(item => <div className="metric" key={item.label}><div><span>{item.label}</span><small>{item.direction}</small></div><strong>{decimal(item.value)}</strong><p>{item.explanation}</p></div>)}</div></section>
      <div className="charts-grid"><section className="card"><SectionTitle title="概率可靠性曲线" description="曲线越贴近对角线，预测概率与实际频率越一致。" action={<Badge>测试集</Badge>}/><ReliabilityChart metrics={metrics}/></section><section className="card"><SectionTitle title="特征缺失分布" description="观察训练与测试数据的缺失模式是否一致。"/><MissingChart data={result.feature_quality}/></section></div>
      <section className="card"><SectionTitle title="全部模型与校准结果" description="保留全部候选；工作台不根据测试集表现自动挑选模型。"/><div className="table-wrap"><table className="metrics-table"><thead><tr><th>模型</th><th>概率处理</th><th>AUC ↑</th><th>Brier ↓</th><th>ECE ↓</th><th>F1 @ 0.5</th><th>Log loss ↓</th></tr></thead><tbody>{result.metrics.map(item => <tr className={item.model === model && item.calibration === calibration ? 'highlight-row' : ''} key={`${item.model}-${item.calibration}`}><td><button className="table-select" onClick={() => { setModel(item.model); setCalibration(item.calibration); }}>{item.model === model && item.calibration === calibration && <Check size={13}/>} {modelNames[item.model] || item.model}</button></td><td>{calibrationNames[item.calibration] || item.calibration}</td><td>{decimal(item.auc, 4)}</td><td>{decimal(item.brier, 4)}</td><td>{decimal(item.ece, 4)}</td><td>{decimal(item.f1, 4)}</td><td>{decimal(item.log_loss, 4)}</td></tr>)}</tbody></table></div></section>
      <section className="card split-card"><SectionTitle title="可信分析的边界" description="预处理只在训练数据上拟合，各阶段使用独立样本。"/><div className="split-bar">{[{ key: 'train', name: '训练集', description: '拟合预处理与模型' }, { key: 'calibration', name: '校准集', description: '拟合概率校准映射' }, { key: 'test', name: '测试集', description: '仅用于最终效果评估' }].map(part => <div key={part.key} style={{ flex: result.split_sizes[part.key as keyof typeof result.split_sizes] }}><strong>{part.name} <span>{number(result.split_sizes[part.key as keyof typeof result.split_sizes])}</span></strong><small>{part.description}</small></div>)}</div><p className="muted small">有效分析样本 {number(result.rows)} 条 · 随机种子 {run.config.seed} · 所有批量评分复用本次冻结的特征处理、模型与校准器。</p></section>
    </>}
    <section className="card provenance"><details><summary><Settings2 size={17}/><strong>分析配置与可追溯信息</strong><span>查看字段、随机种子与运行来源</span><ChevronRight size={17}/></summary><div className="provenance-body"><div className="config-list"><div><span>目标字段</span><strong>{run.config.target_column}</strong></div><div><span>正类值</span><strong>{run.config.positive_value}</strong></div><div><span>正类含义</span><strong>{run.config.positive_label}</strong></div><div><span>记录 ID（不参与建模）</span><strong>{run.config.id_column || '未设置，使用行序号'}</strong></div><div><span>随机种子</span><strong>{run.config.seed}</strong></div><div><span>特征数</span><strong>{run.config.feature_columns.length}</strong></div></div><h3>入模特征</h3><div className="feature-tags">{run.config.feature_columns.map(column => <Badge key={column}>{column}{run.config.categorical_columns.includes(column) ? ' · 类别' : ''}</Badge>)}</div>{result && <><h3>运行来源与复现记录</h3><pre>{JSON.stringify(result.provenance, null, 2)}</pre></>}</div></details></section>
  </>;
}

function NewRunModal({ datasets, initialDataset, onClose, onCreated }: { datasets: Dataset[]; initialDataset: string; onClose: () => void; onCreated: (run: Run) => Promise<void> }) {
  const [datasetId, setDatasetId] = useState(initialDataset || datasets[0]?.id || '');
  const [step, setStep] = useState(0), [name, setName] = useState(''), [target, setTarget] = useState(''), [positive, setPositive] = useState(''), [meaning, setMeaning] = useState(''), [idColumn, setIdColumn] = useState('');
  const [features, setFeatures] = useState<string[]>([]), [categorical, setCategorical] = useState<string[]>([]), [models, setModels] = useState(['logistic', 'random_forest']), [seed, setSeed] = useState(42), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const dialog = useRef<HTMLDivElement>(null);
  const closeDialog = useRef(onClose);
  closeDialog.current = onClose;
  const dataset = datasets.find(item => item.id === datasetId);
  // Refreshes replace dataset objects. Initialize only when the selected identity changes.
  useEffect(() => { if (!dataset) return; const defaultTarget = dataset.columns.find(column => column.name === 'outcome')?.name || ''; setTarget(defaultTarget); setPositive(defaultTarget ? '1' : ''); setMeaning(defaultTarget && dataset.source === 'demo' ? '合成示例中的正类事件（outcome = 1）' : ''); setIdColumn(''); setFeatures(dataset.columns.filter(column => column.name !== defaultTarget).map(column => column.name)); setCategorical(dataset.columns.filter(column => column.kind === 'categorical' && column.name !== defaultTarget).map(column => column.name)); setName(`${dataset.name.replace(/\.csv$/i, '').slice(0, 90)} · 分析`); }, [datasetId]);
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; const oldOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; dialog.current?.focus(); const handler = (event: KeyboardEvent) => { if (event.key === 'Escape' && !busy) closeDialog.current(); if (event.key === 'Tab' && dialog.current) { const nodes = [...dialog.current.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]')]; const first = nodes[0], last = nodes[nodes.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } }; document.addEventListener('keydown', handler); return () => { document.body.style.overflow = oldOverflow; document.removeEventListener('keydown', handler); previous?.focus(); }; }, [busy]);
  const choices = dataset?.columns.filter(column => column.name !== target && column.name !== idColumn) || [];
  const selectedFeatures = features.filter(column => column !== target && column !== idColumn);
  function toggle(value: string, selected: string[], update: (value: string[]) => void) { update(selected.includes(value) ? selected.filter(item => item !== value) : [...selected, value]); }
  function next() { setError(''); if (!dataset) return setError('请先选择一个数据集。'); if (step === 0 && (!name.trim() || !target || !positive.trim() || !meaning.trim())) return setError('请填写分析名称、目标字段、正类值与正类含义。'); if (step === 0 && idColumn === target) return setError('记录 ID 不能同时作为目标字段。'); if (step === 1 && !selectedFeatures.length) return setError('请至少选择一个入模特征。'); setStep(step + 1); }
  async function submit() { if (!models.length) return setError('请至少选择一个模型。'); if (!Number.isInteger(seed) || seed < 0 || seed > 2147483647) return setError('随机种子需为 0 到 2147483647 之间的整数。'); setBusy(true); setError(''); const config: RunConfig = { dataset_id: datasetId, name: name.trim(), target_column: target, positive_value: positive.trim(), positive_label: meaning.trim(), id_column: idColumn || null, feature_columns: selectedFeatures, categorical_columns: categorical.filter(column => selectedFeatures.includes(column)), models, seed }; try { const run = await api<Run>('/runs', { method: 'POST', body: JSON.stringify(config) }); await onCreated(run); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <div className="modal-overlay" onClick={event => { if (event.target === event.currentTarget && !busy) onClose(); }}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="new-analysis-title" tabIndex={-1} ref={dialog}><div className="modal-header"><div><div className="eyebrow">NEW EXPERIMENT</div><h2 id="new-analysis-title">创建新的分析</h2></div><button className="icon-button" aria-label="关闭新建分析" disabled={busy} onClick={onClose}><X size={21}/></button></div><div className="wizard-steps">{['定义分析', '选择特征', '模型与确认'].map((label, index) => <div className={index === step ? 'active' : index < step ? 'done' : ''} key={label}><span>{index < step ? <Check size={14}/> : index + 1}</span>{label}</div>)}</div><div className="modal-body">{!datasets.length ? <Empty title="还需要一份数据" detail="先到数据资产页面上传 CSV，或导入合成示例，再创建分析。"/> : <>
      {step === 0 && <><label className="field">选择数据集<select value={datasetId} onChange={event => setDatasetId(event.target.value)}>{datasets.map(item => <option key={item.id} value={item.id}>{item.name} · {number(item.rows)} 行{item.source === 'demo' ? ' · 合成示例' : ''}</option>)}</select></label><label className="field">分析名称<input value={name} maxLength={100} onChange={event => setName(event.target.value)} placeholder="为这次实验起个名字"/></label><div className="form-grid"><label className="field">目标字段<select value={target} onChange={event => { const nextTarget = event.target.value; setFeatures(previous => [...new Set([...previous, ...(target && target !== idColumn ? [target] : [])])].filter(column => column !== nextTarget)); setTarget(nextTarget); setPositive(''); setMeaning(''); }}><option value="">请选择标签字段</option>{dataset?.columns.map(column => <option key={column.name} value={column.name}>{column.name} · {column.unique_count} 种取值</option>)}</select></label><label className="field">正类值<input list="target-values" value={positive} onChange={event => setPositive(event.target.value)} placeholder="例如 1、yes 或 default"/><datalist id="target-values">{dataset?.columns.find(column => column.name === target)?.sample_values.map(value => <option key={value} value={value}/>)}</datalist></label></div><label className="field">正类事件含义<input value={meaning} maxLength={120} onChange={event => setMeaning(event.target.value)} placeholder="例如：未来 90 天内发生逾期"/><small>这是输出概率代表的事件。请依据数据定义填写，系统不会推断“违约”或“通过”。</small></label><label className="field">记录 ID <span className="optional">可选，自动排除出模型特征</span><select value={idColumn} onChange={event => { const nextId = event.target.value; setFeatures(previous => [...new Set([...previous, ...(idColumn && idColumn !== target ? [idColumn] : [])])].filter(column => column !== nextId)); setIdColumn(nextId); }}><option value="">不指定，评分时使用行序号</option>{dataset?.columns.filter(column => column.name !== target).map(column => <option key={column.name} value={column.name}>{column.name}</option>)}</select><small>若指定，训练数据与评分数据均须提供非空且唯一的 ID。</small></label></>}
      {step === 1 && <><div className="selection-summary"><div><h3>选择用于建模的字段</h3><p>已排除目标字段{ idColumn ? '与记录 ID' : '' }。请主动排除事后信息与标签衍生字段。</p></div><Badge>{selectedFeatures.length} / {choices.length} 已选</Badge></div><div className="feature-toolbar"><button className="text-button" onClick={() => setFeatures(choices.map(column => column.name))}>全选</button><button className="text-button" onClick={() => setFeatures([])}>清空</button><span>类别字段按离散取值处理，也可用于数值编码的类别。</span></div><div className="feature-options">{choices.map(column => <div className={`feature-option ${selectedFeatures.includes(column.name) ? 'selected' : ''}`} key={column.name}><label><input type="checkbox" checked={selectedFeatures.includes(column.name)} onChange={() => toggle(column.name, features, setFeatures)}/><div><strong>{column.name}</strong><small>缺失 {percent(column.missing_rate)} · {number(column.unique_count)} 种取值</small></div></label><label className="category-toggle"><input type="checkbox" checked={categorical.includes(column.name)} disabled={!selectedFeatures.includes(column.name)} onChange={() => toggle(column.name, categorical, setCategorical)}/>作为类别</label></div>)}</div></>}
      {step === 2 && <><div className="selection-summary"><div><h3>选择比较的模型</h3><p>每个模型都评估原始概率、Platt 与 Isotonic 三种结果。</p></div></div><div className="model-options">{[{ key: 'logistic', description: '线性基线 · 快速、直观' }, { key: 'random_forest', description: '树集成 · 捕捉非线性关系' }, { key: 'lightgbm', description: '梯度提升 · 表格数据模型' }, { key: 'mlp', description: '神经网络 · 对照模型' }, { key: 'mask_aware_mlp', description: '神经网络 · 显式加入缺失掩码' }].map(item => <label className={`model-option ${models.includes(item.key) ? 'selected' : ''}`} key={item.key}><input type="checkbox" checked={models.includes(item.key)} onChange={() => toggle(item.key, models, setModels)}/><div><strong>{modelNames[item.key]}</strong><small>{item.description}</small></div>{models.includes(item.key) && <CheckCircle2 size={18}/>}</label>)}</div><label className="field seed-field">随机种子<input type="number" min={0} max={2147483647} step={1} value={seed} onChange={event => setSeed(Number(event.target.value))}/><small>固定随机种子以支持复现。样本约按 60% / 20% / 20% 划分。</small></label><div className="review-box"><span>本次分析</span><strong>{name}</strong><p>{number(dataset?.rows)} 行原始数据 · {selectedFeatures.length} 个特征 · {models.length} 个模型</p><p>输出概率代表：<b>{meaning}</b></p></div></>}
    </>}{error && <Alert>{error}</Alert>}</div><div className="modal-footer"><Button variant="ghost" disabled={busy} onClick={step ? () => { setStep(step - 1); setError(''); } : onClose}>{step ? <><ArrowLeft size={15}/>上一步</> : '取消'}</Button><span>第 {step + 1} / 3 步</span>{step < 2 ? <Button disabled={!dataset || busy} onClick={next}>继续<ArrowRight size={15}/></Button> : <Button disabled={busy || !models.length} onClick={() => void submit()}>{busy ? <Loader2 className="spin" size={16}/> : <FlaskConical size={16}/>}提交分析</Button>}</div></div></div>;
}

function ScoringPage({ runs, predictions, onChange, notify, initialRunId }: { runs: Run[]; predictions: Prediction[]; onChange: () => Promise<void>; notify: (text: string) => void; initialRunId: string }) {
  const completed = runs.filter(run => run.status === 'completed' && run.result);
  const [runId, setRunId] = useState(initialRunId || completed[0]?.id || ''), [model, setModel] = useState(''), [calibration, setCalibration] = useState('platt'), [file, setFile] = useState<File | null>(null), [busy, setBusy] = useState(false), [error, setError] = useState(''), [batchId, setBatchId] = useState('');
  const selectedRun = completed.find(run => run.id === runId);
  const batch = predictions.find(item => item.id === batchId) || predictions[0];
  useEffect(() => { if (!runId && completed[0]) setRunId(completed[0].id); }, [completed, runId]);
  useEffect(() => { if (initialRunId) setRunId(initialRunId); }, [initialRunId]);
  useEffect(() => { setModel(selectedRun?.config.models[0] || ''); }, [selectedRun?.id]);
  async function score(event: FormEvent) { event.preventDefault(); if (!file || !selectedRun || !model) return; setBusy(true); setError(''); try { const form = new FormData(); form.append('file', file); form.append('model', model); form.append('calibration', calibration); const result = await api<Prediction>(`/runs/${runId}/predict`, { method: 'POST', body: form }); await onChange(); setBatchId(result.id); notify(`评分完成，共处理 ${number(result.rows)} 条记录。`); } catch (failure) { setError(errorMessage(failure)); } finally { setBusy(false); } }
  return <><div className="page-heading"><div><div className="eyebrow">FROM ANALYSIS TO APPLICATION</div><h1>批量评分</h1><p>用已完成分析的冻结模型，估计新数据中正类事件的发生概率。</p></div></div><div className="scoring-layout"><section className="card scoring-form"><SectionTitle title="创建评分批次" description="模型和预处理保持冻结，评分数据不参与训练。"/>{!completed.length ? <Empty icon={FlaskConical} title="先完成一次分析" detail="完成模型训练后，就可以在这里上传新数据并评分。"/> : <form onSubmit={event => void score(event)}><label className="field">选择已完成的分析<select value={runId} onChange={event => setRunId(event.target.value)}>{completed.map(run => <option key={run.id} value={run.id}>{run.name}</option>)}</select></label><label className="field">评分模型<select value={model} onChange={event => setModel(event.target.value)}>{selectedRun?.config.models.map(value => <option key={value} value={value}>{modelNames[value] || value}</option>)}</select></label><label className="field">概率处理<select value={calibration} onChange={event => setCalibration(event.target.value)}>{Object.entries(calibrationNames).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>{selectedRun && <div className="scoring-event"><span>输出概率的含义</span><strong>{selectedRun.config.positive_label}</strong></div>}<label className={`file-drop ${file ? 'has-file' : ''}`}><Upload size={25}/><strong>{file?.name || '点击选择待评分 CSV'}</strong><span>{file ? `${(file.size / 1024).toFixed(1)} KB · 点击更换文件` : '保持与训练数据一致的特征名称'}</span><input type="file" accept=".csv,text/csv" required aria-label="选择待评分 CSV 文件" onChange={event => { setFile(event.target.files?.[0] || null); setError(''); }}/></label>{selectedRun && <Download path={`/runs/${selectedRun.id}/template`} className="full">下载空白字段模板</Download>}<p className="field-help">仅需模型特征{selectedRun?.config.id_column ? '和记录 ID' : ''}，无需目标标签。缺失必需列或无效数值会被拒绝，新类别将明确提示。</p>{error && <Alert>{error}</Alert>}<Button className="full" type="submit" disabled={busy || !file || !selectedRun || !model}>{busy ? <Loader2 size={16} className="spin"/> : <BarChart3 size={16}/>} {busy ? '正在计算概率…' : '开始批量评分'}</Button></form>}</section><div className="scoring-results">{batch ? <><section className="card"><SectionTitle title="评分结果" description={`${batch.run_name} · ${date(batch.created_at)}`} action={<Download path={`/predictions/${batch.id}/download`}>导出 CSV</Download>}/><div className="batch-labels"><Badge>{modelNames[batch.model] || batch.model}</Badge><Badge>{calibrationNames[batch.calibration] || batch.calibration}</Badge><Badge tone="completed">已完成</Badge></div><div className="batch-stats"><div><span>记录数</span><strong>{number(batch.rows)}</strong></div><div><span>平均正类概率</span><strong>{percent(batch.mean_probability)}</strong></div><div><span>特征缺失率</span><strong>{percent(batch.missing_rate)}</strong></div></div><div className="positive-note"><Gauge size={16}/><span>正类事件：<strong>{batch.positive_label}</strong></span></div>{batch.warnings.map((warning, index) => <Alert key={index} warning>{warning}</Alert>)}</section><section className="card"><SectionTitle title="概率分布" description="每条记录输出一个 0–1 之间的正类概率。"/><ProbabilityHistogram batch={batch}/></section><section className="card"><SectionTitle title="输入质量检查" description="对比本批次与训练数据；未见类别沿用冻结处理规则。"/><div className="table-wrap"><table><thead><tr><th>字段</th><th>训练缺失率</th><th>本批缺失率</th><th>未见类别占比</th></tr></thead><tbody>{batch.quality.map(item => <tr key={item.name}><td className="mono">{item.name}</td><td>{percent(item.training_missing_rate)}</td><td>{percent(item.batch_missing_rate)}</td><td><span className={item.unseen_rate > 0 ? 'warning-text' : 'muted'}>{percent(item.unseen_rate)}</span></td></tr>)}</tbody></table></div></section><section className="card"><SectionTitle title="评分记录预览" description={`展示前 ${batch.preview.length} 条；完整结果可导出 CSV。`}/><div className="table-wrap"><table><thead><tr><th>记录 ID</th><th>正类概率</th><th>缺失字段数</th></tr></thead><tbody>{batch.preview.map((row, index) => <tr key={`${row.record_id}-${index}`}><td className="mono">{row.record_id}</td><td><div className="probability-cell"><span><i style={{ width: `${row.probability * 100}%` }}/></span>{percent(row.probability, 2)}</div></td><td>{row.missing_count}</td></tr>)}</tbody></table></div></section></> : <section className="card scoring-empty"><Empty icon={BarChart3} title="把分析转化为概率结果" detail="选择实验与模型，上传符合字段结构的新数据。评分完成后，在此查看分布、质量检查与记录预览。"/><div className="scoring-promise"><ShieldCheck size={19}/><div><strong>概率有定义，应用有边界</strong><p>正类事件由训练配置明确指定。工作台不自动生成授信、拒贷或额度建议。</p></div></div></section>}</div></div>{predictions.length > 0 && <section className="card"><SectionTitle title="历史评分批次" description="点击批次可重新查看已保存的结果。"/><div className="table-wrap"><table><thead><tr><th>来源分析</th><th>模型 / 概率处理</th><th>记录数</th><th>评分时间</th><th>操作</th></tr></thead><tbody>{predictions.map(item => <tr key={item.id} className={batch?.id === item.id ? 'highlight-row' : ''}><td><button className="table-select" onClick={() => setBatchId(item.id)}>{item.run_name}</button></td><td>{modelNames[item.model] || item.model}<span className="muted"> / {calibrationNames[item.calibration] || item.calibration}</span></td><td>{number(item.rows)}</td><td className="date-cell">{date(item.created_at)}</td><td><button className="text-button" onClick={() => { setBatchId(item.id); window.scrollTo({ top: 0, behavior: 'smooth' }); }}>查看结果<ArrowUpRight size={14}/></button></td></tr>)}</tbody></table></div></section>}</>;
}

function ResearchPage() {
  return <>
    <div className="page-heading"><div><div className="eyebrow">HOW AWARE WORKS</div><h1>方法说明</h1><p>了解工作台如何处理缺失数据、比较模型并解释概率结果。</p></div></div>
    <section className="research-hero">
      <div><Badge tone="synthetic"><BookOpen size={12}/>分析方法</Badge><h2>既看模型能否区分风险，<br/>也看概率是否可靠。</h2><p>AWARE 从数据质量开始，比较模型在独立测试样本上的表现，并检查预测概率与实际发生频率是否接近。每次分析的结果都来自当前导入的数据和实际训练。</p></div>
      <div className="research-principles"><div><Database size={19}/><span>看见缺失</span><p>先查看哪些字段缺失，以及缺失有多严重。</p></div><div><Gauge size={19}/><span>检查概率</span><p>区分模型排序能力与概率可靠程度。</p></div><div><ShieldCheck size={19}/><span>独立评估</span><p>隔离训练、校准与最终测试样本。</p></div></div>
    </section>
    <section className="card"><SectionTitle title="一次分析怎样进行" description="从导入数据到批量评分，每一步都能在工作台查看。"/><div className="table-wrap"><table><thead><tr><th>环节</th><th>工作台会做什么</th><th>为什么要做</th></tr></thead><tbody>
      <tr><td><strong>检查数据</strong></td><td>展示字段类型、缺失率与样本预览。</td><td>先确认输入质量，再决定哪些字段适合建模。</td></tr>
      <tr><td><strong>训练与比较</strong></td><td>使用训练样本拟合模型，在独立测试样本上计算指标。</td><td>观察不同模型在同一份数据上的实际表现。</td></tr>
      <tr><td><strong>校准概率</strong></td><td>用单独的校准样本拟合 Platt 或 Isotonic，再评估概率。</td><td>检查预测的 30% 是否接近实际的 30%。</td></tr>
      <tr><td><strong>批量评分</strong></td><td>使用已保存的模型处理新 CSV，并导出每条记录的概率。</td><td>让一次分析的模型可以重复使用，并检查新数据的缺失变化。</td></tr>
    </tbody></table></div></section>
    <section className="card"><SectionTitle title="怎么看结果" description="指标回答的问题不同，应一起看，也要结合样本量和数据来源理解。"/><div className="table-wrap"><table><thead><tr><th>指标</th><th>它说明什么</th><th>阅读方式</th></tr></thead><tbody>
      <tr><td><strong>ROC AUC</strong></td><td>模型把正类排在负类前面的能力。</td><td>越高通常表示区分能力越好。</td></tr>
      <tr><td><strong>Brier Score</strong></td><td>预测概率与真实结果的平均平方误差。</td><td>越低越好，可用于比较概率质量。</td></tr>
      <tr><td><strong>ECE 与可靠性曲线</strong></td><td>预测概率与实际发生频率的差距。</td><td>越接近理想对角线越好；小样本分箱要谨慎解读。</td></tr>
    </tbody></table></div></section>
    <section className="card methodology"><SectionTitle title="工作台的方法与边界"/><div className="methodology-grid"><article><span>01</span><h3>目标含义由数据决定</h3><p>同样是 0 / 1 标签，不同数据集可能表示不同事件。每次分析都需明确正类值与事件含义，评分沿用该定义。</p></article><article><span>02</span><h3>先划分，再学习</h3><p>约 60% / 20% / 20% 的独立样本用于训练、校准与测试。类别映射和缺失处理只在训练样本上学习。</p></article><article><span>03</span><h3>比较而非自动下结论</h3><p>展示 AUC、Brier、ECE 与可靠性曲线。全部候选结果可查，不用测试集表现自动挑选模型。</p></article><article><span>04</span><h3>演示有明确边界</h3><p>合成数据用于展示产品流程。评分结果只供分析参考，不能直接决定授信、拒贷或贷款额度。</p></article></div></section>
  </>;
}
